create table public.universities(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,name_ar text,created_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),university_id uuid not null references public.universities,slug text unique not null check(slug ~ '^[a-z0-9-]+$'),code text not null,title text not null,title_ar text,title_en text,department text not null,department_ar text,description text,year_level smallint,is_active boolean not null default true,created_at timestamptz not null default now(),unique(university_id,department,code));
create table public.topics(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses,title text not null,title_ar text,sort_order integer not null default 0,created_at timestamptz not null default now(),unique(course_id,title),unique(id,course_id));
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null check(length(display_name) between 2 and 80),avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users on delete cascade,role text not null check(role in ('admin','moderator')),created_at timestamptz not null default now());
create table public.user_courses(user_id uuid not null references auth.users on delete cascade,course_id uuid not null references public.courses on delete cascade,created_at timestamptz not null default now(),primary key(user_id,course_id));
create table public.resources(
 id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses,topic_id uuid,author_id uuid not null references public.profiles,
 title text not null check(length(title) between 4 and 160),description text check(length(description)<=2000),type text not null check(type in ('notes','slides','past_exam','video','question_bank','reference','other')),
 source_kind text not null check(source_kind in ('external','pdf')),external_url text,normalized_url text,storage_path text,semester_label text check(length(semester_label)<=40),is_ai_assisted boolean not null default false,rights_confirmed boolean not null default false check(rights_confirmed),status text not null check(status in ('pending','published','hidden')),
 upvotes_count integer not null default 0 check(upvotes_count>=0),downvotes_count integer not null default 0 check(downvotes_count>=0),score integer generated always as (upvotes_count-downvotes_count) stored,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,course_id),
 foreign key(topic_id,course_id) references public.topics(id,course_id),
 check((source_kind='external' and external_url is not null and normalized_url is not null and storage_path is null and status<>'pending') or (source_kind='pdf' and external_url is null and normalized_url is null and storage_path is not null))
);
create unique index resources_duplicate on public.resources(course_id,normalized_url) where normalized_url is not null and status<>'hidden';
create index resources_course_date on public.resources(course_id,status,created_at desc);create index resources_type on public.resources(course_id,type);create index resources_topic on public.resources(topic_id);create index resources_author on public.resources(author_id);
create table public.resource_votes(resource_id uuid not null references public.resources on delete cascade,user_id uuid not null references auth.users on delete cascade,value smallint not null check(value in(-1,1)),created_at timestamptz not null default now(),primary key(resource_id,user_id));
create table public.resource_saves(resource_id uuid not null references public.resources on delete cascade,user_id uuid not null references auth.users on delete cascade,created_at timestamptz not null default now(),primary key(user_id,resource_id));
create table public.course_highlights(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses,resource_id uuid not null,position smallint not null check(position between 1 and 3),curator_id uuid not null references auth.users,curator_note text check(length(curator_note)<=300),created_at timestamptz not null default now(),unique(course_id,resource_id),unique(course_id,position),foreign key(resource_id,course_id) references public.resources(id,course_id));
create table public.discussions(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses,topic_id uuid,resource_id uuid,author_id uuid not null references public.profiles,title text not null check(length(title) between 4 and 160),body text not null check(length(body) between 8 and 5000),status text not null default 'published' check(status in ('published','hidden')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(topic_id,course_id) references public.topics(id,course_id),foreign key(resource_id,course_id) references public.resources(id,course_id));
create index discussions_course on public.discussions(course_id,status,created_at desc);
create table public.discussion_replies(id uuid primary key default gen_random_uuid(),discussion_id uuid not null references public.discussions on delete cascade,author_id uuid not null references public.profiles,body text not null check(length(body) between 2 and 3000),status text not null default 'published' check(status in ('published','hidden')),created_at timestamptz not null default now());
create index replies_discussion on public.discussion_replies(discussion_id,created_at);
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users,resource_id uuid references public.resources,discussion_id uuid references public.discussions,reply_id uuid references public.discussion_replies,reason text not null check(reason in ('spam','inaccurate','copyright','abusive','other')),details text check(length(details)<=2000),status text not null default 'open' check(status in ('open','resolved','dismissed')),created_at timestamptz not null default now(),check(num_nonnulls(resource_id,discussion_id,reply_id)=1));
create unique index reports_resource on public.reports(reporter_id,resource_id) where resource_id is not null;create unique index reports_discussion on public.reports(reporter_id,discussion_id) where discussion_id is not null;create unique index reports_reply on public.reports(reporter_id,reply_id) where reply_id is not null;
create table public.moderation_actions(id uuid primary key default gen_random_uuid(),actor_id uuid not null references auth.users,target_type text not null,target_id uuid not null,action text not null,reason text not null check(length(reason) between 4 and 1000),created_at timestamptz not null default now());
create table public.mutation_limits(user_id uuid not null references auth.users on delete cascade,action text not null,bucket timestamptz not null,count integer not null,primary key(user_id,action,bucket));
create table public.product_events(id bigint generated always as identity primary key,event text not null check(event in ('resource_opened','resource_submitted','course_followed','resource_voted','resource_saved','question_posted','reply_posted','report_submitted')),actor_id uuid references auth.users on delete set null,course_id uuid references public.courses,resource_id uuid references public.resources,created_at timestamptz not null default now());
create or replace function public.is_moderator() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role in ('admin','moderator'));$$;
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'طالب جديد'),80));return new;end;$$;
create trigger auth_profile after insert on auth.users for each row execute function public.create_profile();
-- All writes go through narrow checked RPCs. No browser UPDATE grants on system columns.
do $$declare t text;begin foreach t in array array['universities','courses','topics','profiles','user_roles','user_courses','resources','resource_votes','resource_saves','course_highlights','discussions','discussion_replies','reports','moderation_actions','mutation_limits','product_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);end loop;end;$$;
grant select on public.universities,public.courses,public.topics,public.profiles,public.resources,public.course_highlights,public.discussions,public.discussion_replies to anon,authenticated;
grant select on public.user_courses,public.resource_votes,public.resource_saves,public.reports,public.moderation_actions to authenticated;
create policy universities_read on public.universities for select using(true);
create policy courses_read on public.courses for select using(is_active);
create policy topics_read on public.topics for select using(exists(select 1 from public.courses where id=course_id));
create policy profiles_read on public.profiles for select using(true);
create policy resources_read on public.resources for select using((status='published' and exists(select 1 from public.courses where id=course_id)) or author_id=auth.uid() or public.is_moderator());
create policy follows_read on public.user_courses for select using(user_id=auth.uid());
create policy votes_read on public.resource_votes for select using(user_id=auth.uid());
create policy saves_read on public.resource_saves for select using(user_id=auth.uid());
create policy highlights_read on public.course_highlights for select using(exists(select 1 from public.resources where id=resource_id and status='published'));
create policy discussions_read on public.discussions for select using((status='published' and exists(select 1 from public.courses where id=course_id) and (resource_id is null or exists(select 1 from public.resources where id=resource_id and status='published'))) or author_id=auth.uid() or public.is_moderator());
create policy replies_read on public.discussion_replies for select using((status='published' and exists(select 1 from public.discussions where id=discussion_id and status='published')) or author_id=auth.uid() or public.is_moderator());
create policy reports_read on public.reports for select using(reporter_id=auth.uid() or public.is_moderator());
create policy moderation_read on public.moderation_actions for select using(public.is_moderator());
-- Internal throttle is transaction-safe and not callable by browsers.
create function public.require_actor(p_action text,p_limit integer default 30) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=auth.uid(); n integer;begin
 if actor is null then raise exception 'authentication required' using errcode='28000';end if;
 insert into public.mutation_limits values(actor,p_action,date_trunc('hour',now()),1) on conflict(user_id,action,bucket) do update set count=public.mutation_limits.count+1 returning count into n;
 if n>p_limit then raise exception 'rate limit exceeded' using errcode='P0001';end if;return actor;end;$$;
create function public.follow_course(p_course uuid) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('follow',60);begin
 if not exists(select 1 from public.courses where id=p_course and is_active) then raise exception 'course unavailable';end if;
 if exists(select 1 from public.user_courses where user_id=actor and course_id=p_course) then delete from public.user_courses where user_id=actor and course_id=p_course;else insert into public.user_courses(user_id,course_id) values(actor,p_course);insert into public.product_events(event,actor_id,course_id) values('course_followed',actor,p_course);end if;end;$$;
create function public.submit_resource(p_course uuid,p_topic uuid,p_title text,p_description text,p_type text,p_url text,p_rights boolean,p_ai boolean default false) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('resource',10); rid uuid;host text;begin
 if not p_rights then raise exception 'rights required';end if;
 if not exists(select 1 from public.courses where id=p_course and is_active) then raise exception 'course unavailable';end if;
 host:=split_part(substring(p_url from '^https://([^/]+)'),':',1);
 if p_url!~'^https://[A-Za-z0-9.-]+[.][A-Za-z]{2,}([/:?]|$)' or p_url ~ '[[:space:]\\]' or host ~ '(^|[.])(localhost|local|internal)$' then raise exception 'unsafe URL';end if;
 select id into rid from public.resources where course_id=p_course and normalized_url=p_url and status<>'hidden';if rid is not null then return rid;end if;
 insert into public.resources(course_id,topic_id,author_id,title,description,type,source_kind,external_url,normalized_url,rights_confirmed,is_ai_assisted,status) values(p_course,p_topic,actor,p_title,p_description,p_type,'external',p_url,p_url,true,p_ai,'published') returning id into rid;
 insert into public.product_events(event,actor_id,course_id,resource_id) values('resource_submitted',actor,p_course,rid);return rid;end;$$;
create function public.edit_resource(p_resource uuid,p_title text,p_description text,p_topic uuid) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('edit',30);begin
 update public.resources set title=p_title,description=p_description,topic_id=p_topic,updated_at=now() where id=p_resource and author_id=actor and status='published';if not found then raise exception 'not authorized';end if;end;$$;
create function public.set_vote(p_resource uuid,p_value integer) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('vote',120);old_value integer; r public.resources;begin
 if p_value not in(-1,1) or p_value is null then raise exception 'invalid vote';end if;
 select * into r from public.resources where id=p_resource for update;
 if not found or r.status<>'published' or r.author_id=actor or not exists(select 1 from public.courses where id=r.course_id and is_active) then raise exception 'resource unavailable for vote';end if;
 select value into old_value from public.resource_votes where resource_id=p_resource and user_id=actor;
 if old_value=p_value then delete from public.resource_votes where resource_id=p_resource and user_id=actor;else insert into public.resource_votes(resource_id,user_id,value) values(p_resource,actor,p_value) on conflict(resource_id,user_id) do update set value=excluded.value;end if;
 update public.resources set upvotes_count=(select count(*) from public.resource_votes where resource_id=p_resource and value=1),downvotes_count=(select count(*) from public.resource_votes where resource_id=p_resource and value=-1) where id=p_resource;
 insert into public.product_events(event,actor_id,course_id,resource_id) values('resource_voted',actor,r.course_id,p_resource);end;$$;
create function public.toggle_save(p_resource uuid) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('save',120);begin
 if not exists(select 1 from public.resources r join public.courses c on c.id=r.course_id where r.id=p_resource and r.status='published' and c.is_active) then raise exception 'resource unavailable';end if;
 if exists(select 1 from public.resource_saves where resource_id=p_resource and user_id=actor) then delete from public.resource_saves where resource_id=p_resource and user_id=actor;else insert into public.resource_saves(resource_id,user_id) values(p_resource,actor);insert into public.product_events(event,actor_id,resource_id) values('resource_saved',actor,p_resource);end if;end;$$;
create function public.ask_question(p_course uuid,p_resource uuid,p_title text,p_body text) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('question',15);rid uuid;begin
 if not exists(select 1 from public.courses where id=p_course and is_active) or (p_resource is not null and not exists(select 1 from public.resources where id=p_resource and course_id=p_course and status='published')) then raise exception 'invalid context';end if;
 insert into public.discussions(course_id,resource_id,author_id,title,body) values(p_course,p_resource,actor,p_title,p_body) returning id into rid;insert into public.product_events(event,actor_id,course_id) values('question_posted',actor,p_course);return rid;end;$$;
create function public.reply_question(p_discussion uuid,p_body text) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('reply',30);begin
 if not exists(select 1 from public.discussions d join public.courses c on c.id=d.course_id where d.id=p_discussion and d.status='published' and c.is_active and (d.resource_id is null or exists(select 1 from public.resources where id=d.resource_id and status='published'))) then raise exception 'discussion unavailable';end if;
 insert into public.discussion_replies(discussion_id,author_id,body) values(p_discussion,actor,p_body);insert into public.product_events(event,actor_id) values('reply_posted',actor);end;$$;
create function public.report_content(p_kind text,p_target uuid,p_reason text,p_details text) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('report',10);begin
 if p_kind not in ('resource','discussion','reply') or not (case p_kind when 'resource' then exists(select 1 from public.resources where id=p_target and status='published') when 'discussion' then exists(select 1 from public.discussions where id=p_target and status='published') else exists(select 1 from public.discussion_replies where id=p_target and status='published') end) then raise exception 'target unavailable';end if;
 insert into public.reports(reporter_id,resource_id,discussion_id,reply_id,reason,details) values(actor,case when p_kind='resource' then p_target end,case when p_kind='discussion' then p_target end,case when p_kind='reply' then p_target end,p_reason,p_details) on conflict do nothing;
 insert into public.product_events(event,actor_id) values('report_submitted',actor);end;$$;
create function public.moderate_report(p_report uuid,p_action text,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('moderate',120); r public.reports;begin
 if not public.is_moderator() or p_action not in('hide','dismiss') or length(p_reason)<4 then raise exception 'not authorized';end if;
 select * into r from public.reports where id=p_report and status='open' for update;if not found then raise exception 'report unavailable';end if;
 if p_action='hide' then
 if r.resource_id is not null then update public.resources set status='hidden' where id=r.resource_id;elsif r.discussion_id is not null then update public.discussions set status='hidden' where id=r.discussion_id;else update public.discussion_replies set status='hidden' where id=r.reply_id;end if;end if;
 update public.reports set status=case when p_action='hide' then 'resolved' else 'dismissed' end where id=p_report;
 insert into public.moderation_actions(actor_id,target_type,target_id,action,reason) values(actor,'report',p_report,p_action,p_reason);end;$$;
create function public.set_highlight(p_course uuid,p_resource uuid,p_position integer,p_note text) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('curate',60);begin
 if not public.is_moderator() then raise exception 'not authorized';end if;
 if p_resource is null then delete from public.course_highlights where course_id=p_course and position=p_position;
 else
 perform 1 from public.resources where id=p_resource and course_id=p_course and status='published' for update;if not found then raise exception 'invalid highlight';end if;
 insert into public.course_highlights(course_id,resource_id,position,curator_id,curator_note) values(p_course,p_resource,p_position,actor,p_note) on conflict(course_id,position) do update set resource_id=excluded.resource_id,curator_id=actor,curator_note=excluded.curator_note;
 end if;insert into public.moderation_actions(actor_id,target_type,target_id,action,reason) values(actor,'course',p_course,'highlight',coalesce(nullif(p_note,''),'تعديل اختيارات المادة'));end;$$;
create function public.update_profile(p_name text) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('profile',10);begin update public.profiles set display_name=p_name,updated_at=now() where id=actor;end;$$;
create function public.record_open(p_resource uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from public.resources r join public.courses c on c.id=r.course_id where r.id=p_resource and r.status='published' and c.is_active) then insert into public.product_events(event,actor_id,resource_id) values('resource_opened',auth.uid(),p_resource);end if;end;$$;
-- Security-definer helper functions are revoked from PUBLIC by default.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.is_moderator() to anon,authenticated;
grant execute on function public.follow_course(uuid),public.submit_resource(uuid,uuid,text,text,text,text,boolean,boolean),public.edit_resource(uuid,text,text,uuid),public.set_vote(uuid,integer),public.toggle_save(uuid),public.ask_question(uuid,uuid,text,text),public.reply_question(uuid,text),public.report_content(text,uuid,text,text),public.moderate_report(uuid,text,text),public.set_highlight(uuid,uuid,integer,text),public.update_profile(text) to authenticated;
grant execute on function public.record_open(uuid) to anon,authenticated;
-- A security-invoker view keeps author/topic joins typed without bypassing RLS.
create view public.resource_cards with (security_invoker=true) as select r.id,r.course_id,r.topic_id,r.author_id,r.title,r.description,r.type,r.source_kind,r.external_url,r.is_ai_assisted,r.created_at,r.status,r.score,p.display_name as author_name,coalesce(t.title_ar,t.title) as topic_title,c.slug as course_slug,coalesce(c.title_ar,c.title) as course_title from public.resources r join public.courses c on c.id=r.course_id join public.profiles p on p.id=r.author_id left join public.topics t on t.id=r.topic_id;
grant select on public.resource_cards to anon,authenticated;
